def group_public_jobs_by_country(jobs: list[dict]) -> list[dict]:
    groups: dict[str, list[dict]] = {}
    for job in jobs:
        key = (job.get("country") or "").strip().lower()
        groups.setdefault(key, []).append(job)
    ordered = sorted(groups.items(), key=lambda item: (country_label(item[0]) or item[0]).lower())
    return [
        {
            "key": key,
            "label": country_label(key) or key,
            "href": f"/jobs?country={key}" if key else "/jobs",
            "jobs": items,
        }
        for key, items in ordered
    ]


def public_jobs_item_list_json_ld(jobs: list[dict], page_url: str) -> str:
    elements = [
        {
            "@type": "ListItem",
            "position": index,
            "url": job_apply_url(job),
            "name": (job.get("title") or "").strip() or "Role",
        }
        for index, job in enumerate(jobs, start=1)
        if (job.get("public_slug") or "").strip()
    ]
    payload = {
        "@context": "https://schema.org",
        "@type": "ItemList",
        "url": page_url,
        "numberOfItems": len(elements),
        "itemListElement": elements,
    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))


def _cdata(text: str) -> str:
    safe = (text or "").replace("]]>", "]]]]><![CDATA[>")
    return f"<![CDATA[{safe}]]>"


def _linkedin_description_html(job: dict) -> str:
    soup = BeautifulSoup(job_posting_description(job), "html.parser")
    for tag in soup.find_all(True):
        if tag.name not in LINKEDIN_DESCRIPTION_TAGS:
            tag.unwrap()
            continue
        tag.attrs = {}
    body = soup.body or soup
    return "".join(str(child) for child in body.children).strip()


def _linkedin_job_xml(job: dict, site: str, company_id: str, poster_email: str) -> str:
    partner_id = str(job.get("id") or "")[:40]
    title = (job.get("title") or "").strip() or "Role"
    apply_url = job_apply_url(job, site)
    fields = [
        ("partnerJobId", partner_id),
        ("company", "Kuchup"),
        ("title", title),
        ("description", _linkedin_description_html(job)),
        ("applyUrl", apply_url),
        ("companyId", company_id),
        ("location", job_location_label(job)),
        ("posterEmail", poster_email),
    ]
    lines = ["    <job>"]
    for name, value in fields:
        if name == "description":
            lines.append(f"      <{name}>{_cdata(value)}</{name}>")
        else:
            lines.append(f"      <{name}>{_cdata(xml_escape(value))}</{name}>")
    lines.append("    </job>")
    return "\n".join(lines)


def linkedin_jobs_xml_text(jobs: list[dict], *, site: str = SITE) -> str:
    company_id = (os.environ.get("LINKEDIN_COMPANY_ID") or "").strip()
    poster_email = (os.environ.get("LINKEDIN_JOB_POSTER_EMAIL") or "").strip()
    job_blocks = [
        _linkedin_job_xml(job, site, company_id, poster_email)
        for job in jobs
        if (job.get("public_slug") or "").strip()
    ]
    body = "\n".join((
        '<?xml version="1.0" encoding="UTF-8"?>',
        "<source>",
        f"    <lastBuildDate>{formatdate(usegmt=True)}</lastBuildDate>",
        f"    <publisherUrl>{xml_escape(site)}</publisherUrl>",
        "    <publisher>Kuchup</publisher>",
        f"    <expectedJobCount>{len(job_blocks)}</expectedJobCount>",
        *job_blocks,
        "</source>",
        "",
    ))
    return body

def _xml_lastmod(row: dict) -> str:
    return iso_date(row.get("last_seen") or row.get("fetched") or "")


def _requested_country() -> str:
    return (request.args.get("country") or "").strip().lower()


def _jobs_hub_groups(jobs: list[dict], country: str) -> list[dict]:
    groups = group_public_jobs_by_country(jobs)
    if not country:
        return groups
    matched = [group for group in groups if group["key"] == country]
    if matched:
        return matched
    return [
        {
            "key": country,
            "label": country_label(country) or country,
            "href": f"/jobs?country={country}",
            "jobs": [],
        }
    ]


def _jobs_hub_context() -> dict:
    country = _requested_country()
    jobs = list_active_public_jobs()
    groups = _jobs_hub_groups(jobs, country)
    listed = [job for group in groups for job in group["jobs"]]
    site = _public_site_url()
    canonical = f"{site}/jobs"
    if country:
        canonical = f"{canonical}?country={country}"
    return {
        "groups": groups,
        "country_nav": group_public_jobs_by_country(jobs),
        "selected_country": country,
        "job_count": len(listed),
        "canonical": canonical,
        "json_ld": public_jobs_item_list_json_ld(listed, canonical),
        "signed_in": current_user_id() is not None,
        "nav_label": "Open workspace" if current_user_id() else "Sign in",
        "nav_title": (current_username() or "") if current_user_id() else "",
    }

def register(app):
    @app.get("/jobs")
    def public_jobs_hub():
        html = render_template("jobs_index.html", **_jobs_hub_context())
        resp = Response(html, mimetype="text/html")
        resp.headers["Cache-Control"] = JOB_PAGE_CACHE
        return resp

    @app.get("/feeds/linkedin-jobs.xml")
    def linkedin_jobs_feed():
        body = linkedin_jobs_xml_text(list_active_public_jobs(), site=_public_site_url())
        resp = Response(body, mimetype="application/xml")
        resp.headers["Cache-Control"] = JOB_PAGE_CACHE
        return resp

    @app.get("/jobs/<slug>")

